// Builds tests/fixtures/old-layout: tests/generator/fastapi-app as the TypeScript Forge (0.5)
// applies it, trimmed. After `bun run build`, on an applied copy of the sample:
//
//   cp -R tests/generator/fastapi-app /tmp/x
//   cd /tmp/x && git init -q && PATH=<dir with a fake claude>:$PATH node <repo>/dist/forge.js apply --yes
//   node <repo>/crates/forge-cli/tests/fixtures/make-old-layout.mjs /tmp/x
//
// Kept: every rules file, the plugin manifest and hooks.json, a few scripts and helpers,
// .forge/.gitignore, the git hook and the settings file, as written. Large generated files
// (check.sh, checks.sh, lib.sh) are replaced by a stub and their recorded hash updated, so the
// old lock stays consistent. `.claude` and `.forge` are stored as `dot-claude` and `dot-forge`
// (the git hook as `git-pre-commit`) so nothing here is read as live configuration.
import { createHash } from "node:crypto";
import { cpSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const src = process.argv[2];
const out = join(dirname(new URL(import.meta.url).pathname), "old-layout");
const lock = JSON.parse(readFileSync(join(src, ".forge/forge.lock.json"), "utf8"));
const kept = new Set([
  ".claude/skills/forge-project/.claude-plugin/plugin.json",
  ".claude/skills/forge-project/hooks/hooks.json",
  ".claude/skills/forge-project/scripts/turn-start.sh",
  ".claude/skills/forge-project/scripts/checks.sh",
  ".claude/skills/forge-project/scripts/lib.sh",
  ".forge/.gitignore",
  ".forge/check.sh",
  ".forge/helpers/ratchet.py",
  ".forge/ast-grep/sgconfig.yml",
  ".git/hooks/pre-commit",
]);
const keep = (p) => p.startsWith(".claude/rules/") || kept.has(p);
const stub = new Set([".forge/check.sh", ".claude/skills/forge-project/scripts/checks.sh", ".claude/skills/forge-project/scripts/lib.sh"]);
const stored = (p) =>
  p
    .replace(/^\.claude\//, "dot-claude/")
    .replace(/^\.forge\//, "dot-forge/")
    .replace(/^\.git\/hooks\/pre-commit$/, "git-pre-commit");
rmSync(out, { recursive: true, force: true });
const files = {};
for (const [p, h] of Object.entries(lock.files)) {
  if (!keep(p)) continue;
  const dest = join(out, stored(p));
  mkdirSync(dirname(dest), { recursive: true });
  if (stub.has(p)) {
    const text = "#!/bin/sh\n# trimmed for the fixture: generated by forge 0.5\n";
    writeFileSync(dest, text);
    files[p] = createHash("sha256").update(text).digest("hex");
  } else {
    cpSync(join(src, p), dest);
    files[p] = h;
  }
}
lock.files = files;
mkdirSync(join(out, "dot-forge"), { recursive: true });
writeFileSync(join(out, "dot-forge/forge.lock.json"), JSON.stringify(lock, null, 2) + "\n");
cpSync(join(src, ".claude/settings.json"), join(out, "dot-claude/settings.json"));
const manifest = Object.entries(files)
  .filter(([p]) => !p.startsWith(".git/"))
  .map(([p, h]) => `${h}  ${p}`);
writeFileSync(join(out, "dot-forge/manifest.sha256"), manifest.join("\n") + "\n");
